+++ build/enum-repro.cpp
@@ -0,0 +1,19 @@
+#include <nlohmann/json.hpp>
+#include <cstdint>
+#include <iostream>
+
+enum class book_id : std::uint64_t;
+
+int main()
+{
+    const book_id large_id = static_cast<book_id>(std::uint64_t(1) << 63);
+    const nlohmann::json j(large_id);
+    const bool positive = j > 0u;
+    const auto text = j.dump();
+    const bool exact = text == "9223372036854775808";
+    const bool is_unsigned = j.is_number_unsigned();
